<?php

namespace App\Enums;

use App\Enums\Concerns\HasLabels;
use App\Enums\Contracts\WithLabels;

/**
 * Which side of the document list a document belongs to.
 *
 * A document is an export when it was generated by a report workflow, which is
 * recorded as a `report_type` tag. Everything else was uploaded by a center and
 * is waiting to be imported.
 */
enum DocumentKindEnum: string implements WithLabels
{
    use HasLabels;

    case IMPORT = 'import';
    case EXPORT = 'export';

    /**
     * The tag key that marks a document as generated rather than uploaded.
     */
    const EXPORT_TAG_KEY = 'report_type';

    public static function labels(): array
    {
        return [
            self::IMPORT->value => 'Import',
            self::EXPORT->value => 'Export',
        ];
    }
}
